#include "spp/model/vsop87d.hpp"

#include <cmath>
#include <span>

#include "spp/vsop87d_earth_terms.inc"   // generated by tools/vsop_gen

namespace spp::model::vsop87d {

namespace {

// X(t) = sum_n ( sum_j A cos(B + C t) ) t^n
double evaluate(const std::span<const Term> (&series)[6], double t) {
    double value = 0.0;
    double t_power = 1.0;
    for (const auto& terms : series) {
        if (!terms.empty()) {
            double inner = 0.0;
            for (const Term& term : terms) inner += term.a * std::cos(term.b + term.c * t);
            value += inner * t_power;
        }
        t_power *= t;
    }
    return value;
}

}  // namespace

Spherical earth(double t) {
    return {evaluate(data::L, t), evaluate(data::B, t), evaluate(data::R, t)};
}

}  // namespace spp::model::vsop87d
